36	namespace Eigen {
37	struct ThreadPoolDevice;
38	}  // end namespace Eigen
39	
40	namespace stream_executor {
41	class Stream;
42	}  // namespace stream_executor
43	
44	namespace tsl {
45	class Env;
46	namespace thread {
47	class ThreadPool;
48	}  // namespace thread
49	}  // namespace tsl
50	namespace tensorflow {
51	
52	class Device;
53	class DeviceAttributes;
54	class EventMgr;
55	class OpKernelContext;
56	class ResourceMgr;
57	class ScopedAllocatorMgr;
58	class TensorProto;
59	
60	// A wrapper for an Eigen Gpu Device that includes per-op state. The
61	// class is defined even for non-GPU devices since the
62	// OpKernelContext::Params structure wants to fill it in.
63	class PerOpGpuDevice {
64	 public:
65	  virtual ~PerOpGpuDevice() = default;
66	  virtual const Eigen::GpuDevice& device() const = 0;
67	};
68	
69	// A class that devices can subclass to pass around
70	// Device-specific context to OpKernels.
71	class DeviceContext : public core::RefCounted {
72	 public:
73	  ~DeviceContext() override = default;
74	  virtual stream_executor::Stream* stream() const { return nullptr; }
75	  virtual void MaintainLifetimeOnStream(const Tensor* t,
76	                                        stream_executor::Stream* stream) const {
77	  }
78	
79	  // "cpu_tensor" is a tensor on a CPU. Copies "cpu_tensor" into
80	  // "device_tensor" which is on a non-CPU device "device". "device_tensor"
81	  // must be allocated to be of the same size as "cpu_tensor".
82	  virtual void CopyCPUTensorToDevice(const Tensor* cpu_tensor, Device* device,
83	                                     Tensor* device_tensor, StatusCallback done,
84	                                     bool sync_dst_compute = true) const {
85	    done(absl::InternalError("Unrecognized device type in CPU-to-device Copy"));
86	  }
87	
88	  // Same as CopyCPUTensorToDevice, but in a synchronous way.
89	  absl::Status CopyCPUTensorToDeviceSync(const Tensor* cpu_tensor,
90	                                         Device* device,
91	                                         Tensor* device_tensor) const;
92	
93	  // Copies a tensor in this device.
94	  virtual void CopyTensorInSameDevice(const Tensor* input_tensor,
95	                                      Device* device, Tensor* output_tensor,
96	                                      StatusCallback done) const {
97	    done(absl::UnimplementedError("Copy in same device not implemented."));
98	  }
99	
100	  // "device_tensor" is a tensor on a non-CPU device.  Copies
101	  // device_tensor into "cpu_tensor".  "cpu_tensor" must be allocated
102	  // to be of the same size as "device_tensor".
103	  virtual void CopyDeviceTensorToCPU(const Tensor* device_tensor,
104	                                     absl::string_view tensor_name,
105	                                     Device* device, Tensor* cpu_tensor,
106	                                     StatusCallback done) {
107	    done(absl::InternalError("Unrecognized device type in device-to-CPU Copy"));
108	  }
109	
110	  // Same as `CopyDeviceTensorToCPU`, but blocks until the copy is done.
111	  absl::Status CopyDeviceTensorToCPUSync(const Tensor* device_tensor,
112	                                         absl::string_view tensor_name,
113	                                         Device* device, Tensor* cpu_tensor);
114	
115	  // If possible, wait for all events on *stream to complete then execute func.
116	  // A non-OK Status is returned otherwise.  The stream argument should be the
117	  // one provided by AcceleratorDeviceInfo.  This function is not applicable to
118	  // devices that don't provide such a value.
119	  virtual absl::Status ThenExecute(Device* device,
120	                                   stream_executor::Stream* stream,
121	                                   std::function<void()> func) {
122	    return absl::InternalError("ThenExecute not supported by device");
123	  }
124	
125	  // check if device is a pluggable device
126	  virtual bool IsPluggableDevice() { return false; }
127	
128	  // Returns the pinned host memory allocator for the device.
129	  virtual Allocator* host_memory_allocator() const { return nullptr; }
130	};
131	
132	class DeviceBase {
133	 public:
134	  explicit DeviceBase(tsl::Env* env) : env_(env) {}
135	  virtual ~DeviceBase();
136	
137	  tsl::Env* env() const { return env_; }
138	
139	  struct CpuWorkerThreads {
140	    int num_threads = 0;
141	    tsl::thread::ThreadPool* workers = nullptr;
142	  };
143	
144	  // Does not take ownership.
145	  void set_tensorflow_cpu_worker_threads(CpuWorkerThreads* t) {
146	    cpu_worker_threads_ = t;
147	  }
148	
149	  virtual const CpuWorkerThreads* tensorflow_cpu_worker_threads() const {
150	    CHECK(cpu_worker_threads_ != nullptr);
151	    return cpu_worker_threads_;
152	  }
153	
154	  // "stream" is used in special circumstances (such as the
155	  // constructors of Ops) where there is no available OpKernelContext.
156	  // "default_context" is used by OpKernelContext whenever a device does not
157	  // supply a DeviceContext for an op in TryGetDeviceContext() (e.g. when only
158	  // using a single stream.)
159	  // "event_mgr" is used to delay deallocation of temporary GPU buffers.
160	  // TODO(pbar) Work out how to move this out of DeviceBase.
161	  struct AcceleratorDeviceInfo {
162	    // Make sure all the defaults are NULL, so we can spot missing assignments.
163	    stream_executor::Stream* stream = nullptr;
164	    DeviceContext* default_context = nullptr;
165	    DeviceContext* pjrt_context = nullptr;
166	    bool use_pjrt_tensor_buffer = false;
167	    EventMgr* event_mgr = nullptr;
168	    int gpu_id = -1;
169	  };
170	
171	  // Does not take ownership.
172	  void set_tensorflow_accelerator_device_info(
173	      AcceleratorDeviceInfo* device_info) {
174	    accelerator_device_info_ = device_info;
175	  }
176	
177	  virtual const AcceleratorDeviceInfo* tensorflow_accelerator_device_info()
178	      const {
179	    return accelerator_device_info_;
180	  }
181	
182	  // The preferred thread pool for this device. If it is nullptr, the system
183	  // automatically assigns a thread pool for execution.
184	  virtual tsl::thread::ThreadPool* tensorflow_device_thread_pool() {
185	    return device_thread_pool_;
186	  }
187	
188	  // Does not take ownership.
189	  void set_eigen_cpu_device(Eigen::ThreadPoolDevice* d);
190	
191	  // Return the Allocator implementation to use based on the allocator
192	  // attributes requested.  See allocator.h for more details.
193	  virtual Allocator* GetAllocator(AllocatorAttributes /*attr*/) {
194	    LOG(FATAL) << "GetAllocator() is not implemented.";
195	    return nullptr;
196	  }
197	
198	  // This method is provided for backwards compatibility, and will be removed
199	  // in a future release.
200	  ABSL_DEPRECATED("Use `this->GetAllocator()` or `this->GetScopedAllocator()`.")
201	  Allocator* GetStepAllocator(AllocatorAttributes attr, ResourceMgr*) {
202	    return GetAllocator(attr);
203	  }
204	
205	  // Return an Allocator prepared for use in particular places by graph
206	  // optimization
207	  virtual Allocator* GetScopedAllocator(AllocatorAttributes attr,
208	                                        int64_t step_id) {
209	    LOG(FATAL) << "Device does not implement GetScopedAllocator()";
210	    return nullptr;
211	  }
212	
213	  virtual ScopedAllocatorMgr* GetScopedAllocatorMgr() const { return nullptr; }
214	
215	  virtual bool has_eigen_cpu_device() const {
216	    return !eigen_cpu_devices_.empty();
217	  }
218	
219	  virtual const Eigen::ThreadPoolDevice* eigen_cpu_device();
220	
221	  // Caller owns the return value. The OpKernelContext calls this even
222	  // for devices that do not implement an eigen_gpu_device. Overridden
223	  // by GPU devices to return a derived type.
224	  virtual PerOpGpuDevice* MakeGpuDevice() { return nullptr; }
225	
226	  virtual DeviceBase* UnderlyingDevice() { return this; }
227	  virtual const DeviceBase* UnderlyingDevice() const { return this; }
228	
229	  // This is overridden by GPU devices to reinitialize the derived
230	  // type returned by MakeGpuDevice.
231	  virtual absl::Status ReinitializeGpuDevice(OpKernelContext* /*context*/,
232	                                             PerOpGpuDevice* /*device*/,
233	                                             DeviceContext* /*dc*/,
234	                                             Allocator* /*allocator*/) {
235	    return absl::OkStatus();
236	  }
237	
238	  // Unimplemented by default
239	  virtual const DeviceAttributes& attributes() const;
240	  virtual int NumaNode() const { return attributes().locality().numa_node(); }
241	  virtual const std::string& name() const;
242	  virtual const DeviceNameUtils::ParsedName& parsed_name() const;
243	  virtual const std::string& device_type() const;
244	
245	  // Updates `attributes()`, indicating the XLA global ID associated with this
246	  // device. This ID is unique across clients in a multi-client setup. For TPUs
247	  // this does not happen until the TPU system has been initialized.
248	  //
249	  // Implemented in Device.
250	  virtual void set_xla_global_id(int64_t id) {}
251	
252	  // Materializes the given TensorProto into 'tensor' stored in Device
253	  // memory.  Most devices will want to override this.
254	  //
255	  // TODO(vrv): We should be able to put this function into
256	  // OpKernelContext and handle the copies from device memory via send
257	  // and receive nodes, instead of requiring that each device handle
258	  // the copies here as well as in copy ops.
259	  virtual absl::Status MakeTensorFromProto(
260	      const TensorProto& tensor_proto, const AllocatorAttributes alloc_attrs,
261	      Tensor* tensor) {
262	    return absl::InternalError(
263	        "Device does not implement MakeTensorFromProto()");
264	  }
265	
266	  // Some devices (i.e. GPUs) may free device memory prior to its actual use
267	  // being completed on the assumption that subsequent allocations can only be
268	  // used serially with respect to pending uses.  If this function returns a
269	  // non-zero value it is the value of a device-specific counter such that any
270	  // device memory tagged with an earlier freed-at count is really unencumbered
271	  // by pending uses.  For this to be useful the device memory allocator must
272	  // be tagging deallocated memory chunks using the same counter.
273	  virtual uint64_t SafeAllocFrontier(uint64_t old_value) { return 0; }
274	
275	  // Copies `input_tensor` to `output_tensor`, where both tensors are on this
276	  // device. This function assumes that `output_tensor` has already been
277	  // allocated with a buffer that is large enough to hold `input_tensor`'s data.
278	  // Calls `done` from a device-specific thread after copy is finished, which
279	  // may be the same as calling thread.
280	  //
281	  // NOTE(ayushd): This function is for TensorFlow internal use only.  Deep copy
282	  // is discouraged and should not be used in OpKernels.
283	  virtual void CopyTensorInSameDevice(const Tensor* input_tensor,
284	                                      Tensor* output_tensor,
285	                                      const DeviceContext* device_context,
286	                                      StatusCallback done) {
287	    done(absl::InternalError(absl::StrCat(
288	        "Device ", name(), " does not implement ", "CopyTensorInSameDevice")));
289	  }
290	
291	 protected:
292	  // Does not take ownership.
293	  void set_tensorflow_device_thread_pool(tsl::thread::ThreadPool* thread_pool) {
294	    device_thread_pool_ = thread_pool;
295	  }
296	
297	 private:
298	  tsl::Env* const env_;
299	  CpuWorkerThreads* cpu_worker_threads_ = nullptr;
300	  // Set by GPUs as well as by TPU devices.
301	  AcceleratorDeviceInfo* accelerator_device_info_ = nullptr;
302	  tsl::thread::ThreadPool* device_thread_pool_ = nullptr;
303	  std::vector<Eigen::ThreadPoolDevice*> eigen_cpu_devices_;
304	};
305	
306	// Methods to create and check for Symbolic execution devices.
307	// Such devices are mostly used for TF-XLA bridge. TF should not treat these as
308	// normal devices.
309	void AddSymbolicExecutionDevice(absl::string_view device_name);
310	bool IsSymbolicExecutionDevice(absl::string_view device_name);
311	
312	}  // namespace tensorflow
313	
314	#endif  // TENSORFLOW_CORE_FRAMEWORK_DEVICE_BASE_H_
