130	absl::Status DeviceFactory::ListAllPhysicalDevices(
131	    std::vector<std::string>* devices) {
132	  // CPU first. A CPU device is required.
133	  // TODO(b/183974121): Consider merge the logic into the loop below.
134	  auto cpu_factory = GetFactory("CPU");
135	  if (!cpu_factory) {
136	    return absl::NotFoundError(
137	        "CPU Factory not registered. Did you link in threadpool_device?");
138	  }
139	
140	  size_t init_size = devices->size();
141	  TF_RETURN_IF_ERROR(cpu_factory->ListPhysicalDevices(devices));
142	  if (devices->size() == init_size) {
143	    return absl::NotFoundError("No CPU devices are available in this process");
144	  }
145	
146	  // Then the rest (including GPU).
147	  tf_shared_lock l(*get_device_factory_lock());
148	  for (auto& p : device_factories()) {
149	    auto factory = p.second.factory.get();
150	    if (factory != cpu_factory) {
151	      TF_RETURN_IF_ERROR(factory->ListPhysicalDevices(devices));
152	    }
153	  }
154	
155	  return absl::OkStatus();
156	}
157	
158	absl::Status DeviceFactory::ListPluggablePhysicalDevices(
159	    std::vector<std::string>* devices) {
160	  tf_shared_lock l(*get_device_factory_lock());
161	  for (auto& p : device_factories()) {
162	    if (p.second.is_pluggable_device) {
163	      auto factory = p.second.factory.get();
164	      TF_RETURN_IF_ERROR(factory->ListPhysicalDevices(devices));
165	    }
166	  }
167	  return absl::OkStatus();
168	}
