170	absl::Status DeviceFactory::GetAnyDeviceDetails(
171	    int device_index, std::unordered_map<std::string, std::string>* details) {
172	  if (device_index < 0) {
173	    return absl::InvalidArgumentError(
174	        absl::StrCat("Device index out of bounds: ", device_index));
175	  }
176	  const int orig_device_index = device_index;
177	
178	  // Iterate over devices in the same way as in ListAllPhysicalDevices.
179	  auto cpu_factory = GetFactory("CPU");
180	  if (!cpu_factory) {
181	    return absl::NotFoundError(
182	        "CPU Factory not registered. Did you link in threadpool_device?");
183	  }
184	
185	  // TODO(b/183974121): Consider merge the logic into the loop below.
186	  std::vector<std::string> devices;
187	  TF_RETURN_IF_ERROR(cpu_factory->ListPhysicalDevices(&devices));
188	  if (device_index < devices.size()) {
189	    return cpu_factory->GetDeviceDetails(device_index, details);
190	  }
191	  device_index -= devices.size();
192	
193	  // Then the rest (including GPU).
194	  tf_shared_lock l(*get_device_factory_lock());
195	  for (auto& p : device_factories()) {
196	    auto factory = p.second.factory.get();
197	    if (factory != cpu_factory) {
198	      devices.clear();
199	      // TODO(b/146009447): Find the factory size without having to allocate a
200	      // vector with all the physical devices.
201	      TF_RETURN_IF_ERROR(factory->ListPhysicalDevices(&devices));
202	      if (device_index < devices.size()) {
203	        return factory->GetDeviceDetails(device_index, details);
204	      }
205	      device_index -= devices.size();
206	    }
207	  }
208	
209	  return absl::InvalidArgumentError(
210	      absl::StrCat("Device index out of bounds: ", orig_device_index));
211	}
