213	absl::Status DeviceFactory::AddCpuDevices(
214	    const SessionOptions& options, const std::string& name_prefix,
215	    std::vector<std::unique_ptr<Device>>* devices) {
216	  auto cpu_factory = GetFactory("CPU");
217	  if (!cpu_factory) {
218	    return absl::NotFoundError(
219	        "CPU Factory not registered. Did you link in threadpool_device?");
220	  }
221	  size_t init_size = devices->size();
222	  TF_RETURN_IF_ERROR(cpu_factory->CreateDevices(options, name_prefix, devices));
223	  if (devices->size() == init_size) {
224	    return absl::NotFoundError("No CPU devices are available in this process");
225	  }
226	
227	  return absl::OkStatus();
228	}
229	
230	absl::Status DeviceFactory::AddDevices(
231	    const SessionOptions& options, const std::string& name_prefix,
232	    std::vector<std::unique_ptr<Device>>* devices) {
233	  // CPU first. A CPU device is required.
234	  // TODO(b/183974121): Consider merge the logic into the loop below.
235	  TF_RETURN_IF_ERROR(AddCpuDevices(options, name_prefix, devices));
236	
237	  absl::flat_hash_set<std::string> allowed_device_types;
238	  for (const auto& device_filter : options.config.device_filters()) {
239	    DeviceNameUtils::ParsedName parsed;
240	    if (!DeviceNameUtils::ParseFullOrLocalName(device_filter, &parsed)) {
241	      return absl::InvalidArgumentError(
242	          absl::StrCat("Invalid device filter: ", device_filter));
243	    }
244	    if (parsed.has_type) {
245	      allowed_device_types.insert(parsed.type);
246	    }
247	  }
248	
249	  auto cpu_factory = GetFactory("CPU");
250	  // Then the rest (including GPU).
251	  mutex_lock l(*get_device_factory_lock());
252	  for (auto& p : device_factories()) {
253	    if (!allowed_device_types.empty() &&
254	        !allowed_device_types.contains(p.first)) {
255	      continue;  // Skip if the device type is not found from the device filter.
256	    }
257	    auto factory = p.second.factory.get();
