60	                    << " NUMA nodes visible in system, "
61	                    << " assigning device " << name << " to NUMA node "
62	                    << numa_node;
63	        }
64	        DeviceLocality dev_locality;
65	        dev_locality.set_numa_node(numa_node);
66	        tpd = std::make_unique<ThreadPoolDevice>(
67	            options, name, Bytes(256 << 20), dev_locality,
68	            ProcessState::singleton()->GetCPUAllocator(numa_node));
69	      } else {
70	        tpd = std::make_unique<ThreadPoolDevice>(
71	            options, name, Bytes(256 << 20), DeviceLocality(),
72	            ProcessState::singleton()->GetCPUAllocator(port::kNUMANoAffinity));
73	      }
74	      devices->push_back(std::move(tpd));
